import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Контраст — это разница между самой тёмной и самой светлой частями фото. Именно он делает изображение энергичным и плотным или плоским и серым.</p>\n<p>У фото с хорошим контрастом глубокие тени, яркие света и чёткое ощущение глубины. Фото с низким контрастом выглядит туманным, будто его сняли сквозь дымку.</p>\n<p>В этом руководстве мы расскажем, как работает контраст, как хорошо пользоваться ползунком и пресетами и как добавлять энергию, не выжигая света и не задавливая тени. Речь пойдёт о портретах, пейзажах, скриншотах и ошибках, которые портят хороший снимок. Добавить снимку энергии поможет <a href=\"/ru/izmenit-kontrast-izobrazheniya/\">Редактор контрастности изображения</a> — двигайте ползунок, пока тени и света не встанут как надо.</p>\n<h2 id=\"what-contrast-does\">Что на самом деле делает контраст</h2>\n<p>Контраст растягивает или сжимает тональный диапазон изображения. При повышении тёмные пиксели становятся темнее, а светлые — светлее, и разрыв между ними расширяется.</p>\n<p>Понижение контраста делает наоборот. Оно сближает тёмное и светлое, смягчает изображение и уменьшает разницу между его самой яркой и самой тёмной частями.</p>\n<p>Контраст почти не меняет общую яркость. Фото с высоким контрастом может быть тёмным или светлым в целом, но его тени и света в любом случае будут далеко друг от друга.</p>\n<p>Думайте о контрасте как о расстоянии между концами верёвки. Если развести концы, тона изображения растянутся, а если дать им сойтись, они сожмутся в середину.</p>\n<h2 id=\"why-photos-look-flat\">Почему фото выглядят плоскими</h2>\n<p>Дымка — самая частая причина плоского фото. Туман, мгла и влажный воздух рассеивают свет, поднимают тени и тускнят света, пока всё изображение не окажется в середине.</p>\n<p>Пасмурный свет тоже делает фото плоскими. Облачное небо даёт мягкий равномерный свет без сильных теней, поэтому у изображения изначально малый тональный диапазон.</p>\n<p>Отсканированные старые фото тоже часто выглядят плоскими. Возраст выцветает отпечатки, сканер неверно считывает тона, и получается серое мутное изображение без глубоких чёрных и ярких белых цветов.</p>\n<p>Камеры телефонов могут давать плоские фото при слабом свете. Сенсор с трудом захватывает полный диапазон, и изображение получается сжатым в средние тона.</p>\n<p>Плоское фото — не приговор: именно его проще всего спасти, ведь детали в нём есть, просто они спрятаны в середине диапазона. Небольшое повышение контраста на 10–20 процентов чаще всего возвращает снимку жизнь без побочных эффектов.</p>\n<h2 id=\"slider-explained\">Ползунок контраста: объяснение</h2>\n<p>Ползунок контраста идёт от отрицательных значений к положительным, а ноль означает отсутствие изменений. Движение вправо повышает контраст, а влево — понижает его.</p>\n<p>Небольшие сдвиги дают большую разницу. Изменения на 10–20 процентов часто хватает, чтобы исправить плоское фото, а большие сдвиги быстро выжигают света и задавливают тени.</p>\n<p>Сразу после загрузки инструмент показывает ваше фото с контрастом плюс 20 процентов. Эта отправная точка сразу даёт представление о том, как выглядит умеренное повышение контраста.</p>\n<p>Двигайте ползунок медленно и следите за предпросмотром. Живое обновление точно показывает, как реагирует изображение, поэтому можно остановиться, когда фото выглядит правильно.</p>\n<h2 id=\"quick-presets\">Быстрые пресеты для правки в один клик</h2>\n<p>Инструмент включает быстрые пресеты, которые применяют распространённые значения контраста одним нажатием. Это быстрый способ проверить разные уровни, не двигая ползунок.</p>\n<p>Пресеты — это отправная точка, а не окончательный ответ. Нажмите на пресет, посмотрите на предпросмотр, а затем доработайте ползунком, если результат близок, но не совсем точен.</p>\n<p>Используйте пресеты, чтобы быстро сравнить варианты. Пресет на плюс 10 процентов рядом с пресетом на плюс 30 процентов показывает, сколько контраста фото выдерживает, прежде чем начнёт терять детали.</p>\n<p>Для серии похожих фото один и тот же пресет сохраняет результаты едиными. Набор туманных пейзажей, усиленных на одинаковую величину, выглядит как серия.</p>\n<h2 id=\"compare-modes\">Режимы сравнения: «до», «после» и «разделённый экран»</h2>\n<p>Режимы сравнения показывают оригинал и отредактированную версию вместе. В виде «После» видно изображение с повышенным контрастом, в виде «До» — оригинал, а в разделённом виде — оба рядом.</p>\n<p>Разделённое сравнение полезнее всего для работы с контрастом. Оно позволяет точно увидеть, какие тени углубились, а какие света стали ярче, с чёткой линией между двумя версиями.</p>\n<p>Полноэкранное сравнение даёт самый большой вид. Это лучший способ оценить правку контраста, потому что изображение в полном размере показывает потерю деталей, которую скрывает маленький предпросмотр.</p>\n<p>Проверяйте вид сравнения перед каждым скачиванием. Быстрый взгляд ловит выгоревшие света и задавленные тени, которые маленький предпросмотр мог скрыть.</p>\n<p>Разделённое сравнение показывает правку честнее всего: проведите линию взглядом через лицо, небо и тени. Если в одной из этих зон детали исчезли, уменьшите ползунок, даже если остальное фото выглядит отлично.</p>\n<h2 id=\"contrast-and-colour\">Контраст и цвет: как они влияют друг на друга</h2>\n<p>Контраст влияет и на цвет, и на тон. Повышение контраста делает цвета богаче и насыщеннее, потому что тёмное становится темнее, а яркое — ярче вокруг них.</p>\n<p>Понижение контраста приглушает цвета. У мягкого низкоконтрастного изображения нежные пастельные тона, что подходит для портретов и мечтательных пейзажей.</p>\n<p>Эта связь означает, что изменение контраста — это ещё и изменение цвета. Фото, которому нужно больше энергии, может нуждаться в контрасте, а фото, которому нужно больше цвета, — в насыщенности.</p>\n<p>Для работы с цветом используйте <a href=\"/ru/izmenit-nasyshchennost-izobrazheniya/\">редактор насыщенности изображения</a> после настройки контраста. Два регулятора вместе дают полный контроль над видом снимка.</p>\n<h2 id=\"contrast-for-portraits\">Контраст для портретов</h2>\n<p>Портреты нуждаются в бережном контрасте. Лицо со слишком сильным контрастом выглядит жёстким и постаревшим, с глубокими тенями под глазами и яркими пятнами на лбу.</p>\n<p>Начните с небольшого повышения на 10 процентов и проверьте кожу. Лицо должно выглядеть чётким, а не так, будто тени на нём нарисовали.</p>\n<p>Отрицательный контраст может помочь жёсткому портрету. Солнце в полдень создаёт сильные тени на лице, а небольшое снижение смягчает их, не теряя общей формы.</p>\n<p>Для портрета, снятого в мягком свете окна, контраст часто уже правильный. Небольшого повышения на 5–10 процентов хватает, а большие сдвиги приносят больше вреда, чем пользы.</p>\n<h2 id=\"contrast-for-landscapes\">Контраст для пейзажей</h2>\n<p>Пейзажи выигрывают от контраста больше всего. Туманный горный вид, долина в дымке или тусклое небо — всё это приобретает глубину и драму от умеренного повышения.</p>\n<p>Используйте повышение на 15–25 процентов для туманного пейзажа. Тени углубляются, света становятся ярче, а сцена приобретает энергию, которую забрала дымка.</p>\n<p>Следите за небом, когда повышаете контраст. Облака выгорают первыми, превращаясь в белые пятна без формы, и выгоревшее небо портит хороший в остальном пейзаж.</p>\n<p>Для пейзажа с ярким небом и тёмным передним планом примите компромисс. Контраст растягивает оба конца, поэтому небо и земля двигаются в противоположных направлениях.</p>\n<p>В горах и у моря компромисс обычно решают в пользу неба: выгоревшее небо портит пейзаж сильнее, чем тёмный передний план. Пусть земля останется чуть темнее — зритель всё равно сначала смотрит на горизонт и облака.</p>\n<h2 id=\"contrast-for-screenshots\">Контраст для скриншотов и документов</h2>\n<p>Скриншоты и отсканированные документы нуждаются в контрасте для читаемости. Текст должен выделяться на фоне, а низкоконтрастный скан с серым текстом трудно читать.</p>\n<p>Вставьте скриншот прямо сочетанием Ctrl+V, чтобы пропустить шаг сохранения. Изображение сразу появится в редакторе, готовое к настройке.</p>\n<p>Повышайте контраст, пока текст не станет тёмным, а фон — белым. Документ с насыщенным чёрным текстом на чистом белом фоне легко читать и печатать.</p>\n<p>Следите за шумом на фоне. Сильно контрастированный скан может показать крапинки и артефакты, особенно в JPEG, который уже был сжат.</p>\n<h2 id=\"negative-contrast\">Отрицательный контраст: смягчение жёстких фото</h2>\n<p>Отрицательный контраст смягчает изображение, сближая тёмное и светлое. Это правильный выбор для фото, снятого при жёстком полуденном солнце.</p>\n<p>Используйте значения вроде минус 10 или минус 20 процентов, чтобы смягчить сильные тени на портрете. Лицо сохраняет форму, но жёсткие края растворяются в более мягкий вид.</p>\n<p>Отрицательный контраст также подходит мечтательным мягким пейзажам. Туманная утренняя сцена с низким контрастом кажется спокойной и тихой, что совпадает с настроением фото.</p>\n<p>Не переусердствуйте. Фото со слишком малым контрастом выглядит серым и безжизненным, будто его сняли сквозь туман, даже в ясный день.</p>\n<p>Отрицательный контраст хорошо работает и для фото в стиле «плёнка»: мягкие тона и приглушённые тени создают ностальгическое настроение. Попробуйте минус 10 процентов на повседневных снимках — результат часто оказывается приятнее, чем вы ожидали.</p>\n<h2 id=\"clipping-and-crushing\">Выгорание светов и задавливание теней</h2>\n<p>Выгорание происходит, когда света доводят за пределы чистого белого цвета. Детали в ярком облаке или белой рубашке исчезают, и область становится бесформенным пятном.</p>\n<p>Задавливание происходит, когда тени доводят за пределы чистого чёрного цвета. Детали в тёмном пальто или затенённом углу исчезают, и область становится сплошным чёрным пятном.</p>\n<p>И то и другое необратимо в сохранённом файле. Когда деталь выгорела или задавлена, никакая дальнейшая правка её не вернёт, поэтому проверяйте крайние точки перед скачиванием.</p>\n<p>Используйте вид сравнения, чтобы заметить выгорание и задавливание. Разделённый вид точно показывает, какие области потеряли детали, а небольшое уменьшение ползунка обычно их возвращает.</p>\n<h2 id=\"formats-and-export\">Форматы и сохранение</h2>\n<p>Инструмент принимает распространённые форматы изображений, включая JPG, PNG, WebP и HEIC, с файлами до 20 МБ. Сохранять можно в JPG, PNG или WebP — в зависимости от ваших нужд.</p>\n<p>Сохранение в PNG или WebP сохраняет прозрачность исходного изображения. Если ваш исходник — прозрачная PNG-графика, отредактированная по контрасту копия сохранит сквозные области целыми.</p>\n<p>Для фото хорошо подходит JPG с высоким качеством. Контраст почти не добавляет веса файлу, поэтому сохранённая копия остаётся близкой к оригиналу по размеру.</p>\n<p>Ползунок качества появляется при сохранении в JPG и WebP и скрывается для PNG, потому что PNG работает без потерь и настройки качества у него нет.</p>\n<h2 id=\"contrast-vs-brightness\">Контраст и яркость: что первым?</h2>\n<p>Яркость задаёт общий уровень, а контраст — разброс вокруг этого уровня. Слишком тёмному фото сначала нужна яркость, потому что контраст уровень не исправит.</p>\n<p>Плоскому, но правильно освещённому фото нужен только контраст. Его осветление сделает его ярче и площе, а не лучше, поэтому пропустите шаг яркости.</p>\n<p>Когда фото нуждается в обоих, делайте сначала яркость, затем контраст. Порядок важен, потому что яркость меняет то, что должен сделать контраст.</p>\n<p>Полное сравнение читайте в статье <a href=\"/ru/blog/yarkost-ekspozitsiya-kontrast-otlichiya/\">Яркость, экспозиция и контраст: основы редактирования</a>.</p>\n<h2 id=\"privacy-local-processing\">Конфиденциальность: редактирование без загрузки на сервер</h2>\n<p>Всё редактирование контраста происходит в вашем браузере. Фото никуда не загружаются, что важно, когда речь идёт о личных и семейных снимках или работе для клиентов.</p>\n<p>Это настоящее преимущество перед облачными редакторами. Семейное фото или личный документ не должны отправляться на неизвестный сервер только ради добавления контраста.</p>\n<p>Инструмент также удаляет GPS-данные EXIF при сохранении. В скачанном фото с изменённым контрастом не будет записи о том, где оно было сделано.</p>\n<p>Храните исходное фото без правок. Когда изменение контраста «впечатано» в сохранённый файл, отменить его из этого файла уже нельзя, поэтому оригинал — ваша единственная чистая копия.</p>\n<h2 id=\"common-mistakes\">Частые ошибки при настройке контраста</h2>\n<p>Самая частая ошибка — добавить слишком много контраста. Фото, доведённое до плюс 50 процентов и больше, полностью теряет света и тени, и получается жёсткое изображение, похожее на плакат.</p>\n<p>Ещё одна ошибка — использовать контраст, чтобы исправить тёмное фото. Тёмное фото с высоким контрастом остаётся тёмным, просто с более глубокими тенями, а объект остаётся скрытым.</p>\n<p>Многие забывают проверять крайние точки. Небо или тень, которые хорошо выглядят в маленьком предпросмотре, в полном размере могут оказаться выгоревшими или задавленными, поэтому всегда проверяйте результат в большом виде.</p>\n<p>И наконец, не настраивайте один и тот же JPG снова и снова. Каждое сохранение добавляет повреждения, поэтому для другого уровня контраста всегда возвращайтесь к исходному файлу.</p>\n<h2 id=\"contrast-workflow\">Порядок работы для чистых правок контраста</h2>\n<p>Начните с исходного файла и решите, плоское фото, жёсткое или с правильным разбросом. Плоскому нужно повышение, жёсткому — снижение, а правильному — ничего.</p>\n<p>Примените контраст, затем проверьте вид сравнения. Разделённый вид точно показывает, какие тени углубились, а какие света стали ярче.</p>\n<p>Проверьте света и тени отдельно. Света выгорают первыми при повышении, а тени задавливаются первыми при том же сдвиге, поэтому обе крайности нуждаются во внимании.</p>\n<p>Сохраните с высоким качеством и проверьте результат в полном размере. Приблизьте яркие и тёмные области и убедитесь, что детали не потеряны.</p>\n<p>Полезная привычка — проверять правку на следующий день свежим взглядом. Глаз привыкает к контрасту за время работы, и то, что вечером казалось идеальным, утром может оказаться перебором. Один взгляд на следующий день экономит повторную правку.</p>\n<h2 id=\"contrast-for-black-white\">Контраст для чёрно-белых фото</h2>\n<p>Чёрно-белые фото живут или умирают от контраста. Без цвета, который нёс бы изображение, тональный диапазон — это всё, а плоское чёрно-белое фото выглядит серым и безжизненным.</p>\n<p>Для чёрно-белых фото используйте более сильное повышение контраста, чем для цветных. Повышение на 20–30 процентов даёт изображению глубокие чёрные и яркие белые цвета, которые делают его выразительным.</p>\n<p>Следите за средними тонами, когда повышаете контраст. Чёрно-белому портрету нужны плавные серые тона кожи, а слишком сильный контраст превращает лицо в жёсткие чёрные и белые пятна.</p>\n<p>Для чёрно-белого пейзажа контраст — ваш главный инструмент. Горы, небо и передний план приобретают чёткость благодаря ясному тональному разбросу.</p>\n<p>Попробуйте перевести в чёрно-белый пейзаж, который в цвете кажется скучным: без цвета на первый план выходят форма и свет, и снимок часто преображается. Если после перевода фото стало интереснее — значит, его сила была в композиции, а не в цвете.</p>\n<p>Пошаговый процесс смотрите в статье <a href=\"/ru/blog/kak-nastroit-kontrast-izobrazheniya/\">Как настроить контраст изображения</a>. Сравнение читайте в статье <a href=\"/ru/blog/yarkost-ekspozitsiya-kontrast-otlichiya/\">Яркость, экспозиция и контраст: основы редактирования</a>, а чтобы исправить тёмное фото перед добавлением контраста, попробуйте <a href=\"/ru/redaktor-yarkosti-izobrazheniya/\">редактор яркости изображения</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Сколько контраста добавить плоскому фото?","answer":"Начните с 10–20 процентов и проверьте предпросмотр. Большинству плоских фото нужно лишь небольшое повышение, а большие сдвиги быстро выжигают света и задавливают тени. Увеличивайте маленькими шагами и остановитесь, когда изображение станет плотным, не теряя деталей."},{"question":"Почему фото выглядит жёстким после добавления контраста?","answer":"Контраст довели слишком далеко: тени углубились, а света стали ярче той точки, где детали выживают. Уменьшите ползунок, пока кожа, небо и теневые области снова не покажут текстуру. Повышения на 10 процентов часто хватает."},{"question":"Может ли контраст исправить слишком тёмное фото?","answer":"Нет. Контраст меняет разброс, а не уровень, поэтому тёмное фото с высоким контрастом остаётся тёмным, просто с более глубокими тенями. Сначала осветлите фото в редакторе яркости, затем добавьте контраст, если оно выглядит плоским."},{"question":"Положительный или отрицательный контраст использовать для портрета?","answer":"Обычно небольшое положительное повышение на 5–10 процентов: оно подчёркивает лицо без жёсткости. Для портрета, снятого при жёстком полуденном солнце, отрицательный контраст в минус 10–20 процентов смягчает сильные тени и льстит коже."},{"question":"Усиливает ли повышение контраста и цвета?","answer":"Да. Повышение контраста делает цвета богаче, потому что тёмное становится темнее, а яркое — ярче вокруг них. Если цвета стали слишком сильными, слегка уменьшите насыщенность после этого в редакторе насыщенности."},{"question":"Безопасно ли редактировать контраст личного фото в браузерном инструменте?","answer":"Да, потому что вся обработка происходит локально в вашем браузере и ничего не загружается на сервер. Инструмент также удаляет GPS-данные EXIF при сохранении. Храните исходный файл, если хотите попробовать другой уровень контраста позже."}];
